  addBuilding(landmarks.vault.x, landmarks.vault.z, 46, 30, 14, 3, 1);
  // The garage is a wide low workshop.
  addBuilding(landmarks.garage.x, landmarks.garage.z, 70, 44, 10, 6, 0);
  // The safehouse is a small two-storey house.
