      const cur = pts[i];
      const nxt = pts[(i + 1) % pts.length];
      const curIn = cur.z >= 1;
      const nxtIn = nxt.z >= 1;
      if (curIn) out.push(cur);
      if (curIn !== nxtIn) {
        const t = (1 - cur.z) / (nxt.z - cur.z);
        out.push({ x: cur.x + (nxt.x - cur.x) * t, y: cur.y + (nxt.y - cur.y) * t, z: 1 });
