    }
    drawHud(state);
    if (screen === SCREEN_PAUSED) {
      drawPanel('Paused', ['Solmar waits for no one. Except now.'], 'Press P to keep playing');
    } else if (screen === SCREEN_OVER) {
      const busted = state.overReason === 'busted';
